text:
Το παρακάτω συμβόλαιο επιτρέπει σε έναν ιδιοκτήτη να πουλήσει ένα πατίνι και σε έναν αγοραστή να το αγοράσει. Η τιμή είναι 1 ETH και η συναλλαγή ολοκληρώνεται μόνο όταν ο αγοραστής μεταφέρει το ποσό στον πωλητή.

```solidity
pragma solidity ^0.8.0;

contract Patinaki {
    address public owner;
    address public buyer;
    uint256 public price = 1000000000000000000; // 1 ETH

    constructor() {
        owner = msg.sender;
    }

    function sell() public {
        require(msg.sender == owner, "Only owner can sell");
        buyer = msg.sender;
    }

    function buy() public payable {
        require(msg.sender != owner, "Cannot buy from yourself");
        require(msg.sender != address(0), "Buyer must be a real address");
        require(msg.sender == buyer, "Buyer must be the current owner");
        require(msg.sender.transfer(price), "Transfer failed");
        owner = address(0);
        buyer = address(0);
    }
}
```

Το συμβόλαιο ορίζει τον ιδιοκτήτη, τον αγοραστή, την τιμή και τις συναρτήσεις πώλησης και αγοράς. Η `msg.sender` είναι η διεύθυνση του χρήστη που εκτελεί την τρέχουσα συναλλαγή. Η `transfer` μεταφέρει το ποσό από τον αγοραστή στον πωλητή και η `owner` γίνεται `address(0)` όταν ολοκληρωθεί η πώληση.

