def max_product(nums):
    if not nums:
        return None
    max1, max2, min1, min2 = float('-inf'), float('-inf'), float('inf'), float('inf')
    for num in nums:
        if num > max1:
            max2, max1 = max2, max1 * num
        elif num > max2:
            max2 = max1 * num
        if num < min1:
            min2, min1 = min2, min1 * num
        elif num < min2:
            min2 = min1 * num
    return max(max1, max2)

